/* ---------- v11: métodos escondidos e jornada por dificuldade ---------- */
(function(C){
// A professora pediu para tirar o Ponto Fixo por enquanto. Para trazer de volta, deixe a lista vazia: C.HIDDEN=[].
// O motor, o conteúdo, o Treino e o progresso do Ponto Fixo continuam guardados: o método só some das telas.
C.HIDDEN=['fixedpoint'];
// v12: a Arena saiu do site (no lugar dela, a página Jogos). C.ARENA continua aqui por dois motivos: os desafios numéricos
// viraram as perguntas "relâmpago" do Bobo da Corte (antigo Quem Divergiu?) e os ids a:* de backups antigos continuam válidos.
C.isHidden=id=>C.HIDDEN.includes(id);
C.ALL_METHODS=C.METHODS.slice();C.ALL_CASES=C.CASES.slice();
C.METHODS=C.METHODS.filter(m=>!C.isHidden(m.id));
C.CASES=C.CASES.filter(c=>!C.isHidden(c.method));
// Os desafios da Arena guardam o progresso pela posição (a:0, a:1...), então a lista fica inteira e a tela pula os escondidos.
C.arenaVisible=()=>C.ARENA.map((t,i)=>i).filter(i=>!C.isHidden(C.ARENA[i].method));
// Jornada: do mais fácil ao mais difícil. Cada mundo é um método; o próximo abre quando o Nível 1 do anterior termina.
// A ordem segue o que cada método pede de quem aprende (sinal → corda → derivada → dois pontos → matriz → iteração em sistemas).
C.JOURNEY=[
 {id:'bisection',stars:1,tier:'Fácil',why:'Só pede calcular f e olhar o sinal. A raiz fica sempre cercada e o erro cai pela metade a cada passo: é o jeito mais tranquilo de entender o que é iterar.'},
 {id:'falseposition',stars:2,tier:'Fácil',why:'Mesma ideia do intervalo, com uma conta a mais: a fórmula da corda. Vem logo depois porque reaproveita tudo da Bisseção.'},
 {id:'fixedpoint',stars:3,tier:'Médio',why:'Exige reescrever a equação como x = g(x) e conferir se |g′| < 1.'},
 {id:'newton',stars:3,tier:'Médio',why:'Precisa da derivada e de um bom chute inicial, e pode divergir. Derivada é um ponto fraco comum, então ele vem depois dos métodos de intervalo.'},
 {id:'secant',stars:3,tier:'Médio',why:'É o Newton sem derivada: troca a tangente por uma reta entre dois pontos. Fica depois do Newton porque se apoia nele, e é o método que a turma mais confunde com a Falsa Posição.'},
 {id:'gauss',stars:4,tier:'Difícil',why:'Abre um assunto novo, sistemas lineares. A ideia é o escalonamento, mas a conta é longa e o pivô exige atenção a cada linha.'},
 {id:'seidel',stars:5,tier:'Difícil',why:'Junta tudo: sistema e iteração. Pede entender quando a iteração converge (dominância diagonal) e quando parar.'}
].filter(w=>!C.isHidden(w.id));
C.JOURNEY_NOTE='A ordem segue o que cada método exige: primeiro só o sinal de f, depois a corda, a derivada, a reta entre dois pontos, a matriz e, por fim, a iteração em sistemas. Duas observações de pesquisa ajudaram: alunos confundem o princípio da Secante com o da Falsa Posição (em um estudo com 68 estudantes, só 34,8% acertaram o princípio da Secante, contra 77,9% na fórmula do Newton) e derivadas são um ponto fraco frequente em engenharia. É uma hipótese de ordem: o uso com a turma pode ajustá-la.';
C.TIER_OF=Object.fromEntries(C.JOURNEY.map(w=>[w.id,w.tier]));
// Glossário sem o que só faz sentido para o método escondido.
if(C.isHidden('fixedpoint')){C.GLOSSARY=C.GLOSSARY.filter(g=>g[0]!=='Contração').map(([t,d])=>[t,d.replace(', Ponto Fixo)',')')]);}
})(window.NumeraContent);
